'use strict';

// MODULES //

var objectKeys = require( '@stdlib/utils/keys' );
var format = require( '@stdlib/string/format' );
var defaults = require( './../defaults.js' );


// MAIN //

/**
* Adds a padding menu to an editor.
*
* @private
* @param {Editor} editor - editor instance
* @param {Object} conf - editor padding configuration
* @returns {(Object|null)} menu tree
*/
function addMenu( editor, conf ) {
	var controllers;
	var controller;
	var folder;
	var keys;
	var def;
	var d;
	var i;
	var k;

	keys = objectKeys( conf );
	if ( keys.length === 0 ) {
		return null;
	}
	folder = editor.addFolder( 'Padding' );
	folder.close();

	def = defaults.padding;
	controllers = {};
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		d = def[ k ];
		controller = folder.add( conf, k ).step( d.step );
		controller.name( format( '%s (%s)', k, d.units ) );
		controllers[ k ] = controller;
	}
	return {
		'folder': folder,
		'controllers': controllers
	};
}


// EXPORTS //

module.exports = addMenu;
